SELECT `Product Code`, `Product Name`, Category, `List Price`, `Standard Cost`, pm AS `Profit Margin`
FROM (SELECT *, (`List Price` - `Standard Cost`) / `Standard Cost` AS pm FROM products) t
WHERE pm >= 0.5;

SELECT DISTINCT Category, COUNT(*) OVER (PARTITION BY Category) AS n_products, ROUND(AVG(`List Price`) OVER (PARTITION BY Category), 2) AS avg_price
FROM products
ORDER BY n_products DESC, Category;

SELECT c.ID, c.Company, (SELECT COUNT(*) FROM orders o WHERE o.`Customer ID` = c.ID) AS n_orders
FROM customers AS c
ORDER BY n_orders = 0 DESC, c.Company;

SELECT s.ID, s.Company, pt.`Payment Type`,
       (SELECT COUNT(*) FROM orders o WHERE o.`Shipper ID` = s.ID AND o.`Payment Type` = pt.`Payment Type`)
FROM shippers s, (SELECT DISTINCT `Payment Type` FROM orders WHERE `Payment Type` IS NOT NULL) pt;

