SELECT CONCAT(y, '-', LPAD(m, 2, '0')), MONTHNAME(MAKEDATE(y, 1) + INTERVAL (m - 1) MONTH), COUNT(*), ROUND(SUM(f), 2)
FROM (SELECT YEAR(`Order Date`) AS y, MONTH(`Order Date`) AS m, `Shipping Fee` AS f FROM orders) t
GROUP BY y, m ORDER BY y, m;

SELECT Company, COUNT(*), ROUND(AVG(d), 1), MAX(d), SUM(CASE WHEN d = 0 THEN 1 ELSE 0 END)
FROM (SELECT s.ID, s.Company, DATEDIFF(o.`Shipped Date`, o.`Order Date`) AS d FROM orders o JOIN shippers s ON s.ID = o.`Shipper ID` WHERE o.`Shipped Date` IS NOT NULL) t
GROUP BY ID, Company;

SELECT `Invoice ID`, `Order ID`, DATE_FORMAT(`Invoice Date`, '%d/%m/%Y'), DAYNAME(`Invoice Date`),
       DATE_FORMAT(`Invoice Date` + INTERVAL 30 DAY, '%d/%m/%Y'), DATEDIFF(CURDATE(), DATE(`Invoice Date` + INTERVAL 30 DAY))
FROM invoices ORDER BY `Invoice Date`, `Invoice ID` LIMIT 5;

